_LUT = np.full(256, -1, dtype=np.int64)
for _t, _c in enumerate(ALPH):
    _LUT[ord(_c)] = _t
def _dec(s, scale, shape):
    d = _LUT[np.frombuffer(s.encode(), dtype=np.uint8)].reshape(-1, 2)
    return ((d[:, 0] * 64 + d[:, 1] - 2048).astype(float) * scale).reshape(shape)
T8 = _dec(_T, 0.0006229367, (113, 8))
CODE = _dec(_P, 0.028169308676467022, (113, 9))
W10 = _dec(_W, 0.017853493480880226, (10, 113))
def _near(v, TT):
    return ((v[:, None, :] - TT[None, :, :]) ** 2).sum(-1).argmin(1)
def model(x, iv):
    t0 = iv("tok0", T8[x[:, 0]])
    t1 = iv("tok1", T8[x[:, 1]])
    p = (_near(t0, T8) * _near(t1, T8)) % 113
    pw = iv("post", CODE[p])
    v = iv("code", CODE[_near(pw, CODE)])
    return np.hstack([np.ones((v.shape[0], 1)), v]) @ W10
